 const points=res.pts||[],valid=points.filter(p=>!p.pre&&Number.isFinite(p.raw??p.y)),flagged=valid.filter(p=>p.flags?.length),missing=points.filter(p=>!Number.isFinite(p.raw??p.y)).length,pre=points.filter(p=>p.pre).length;
 const limits=valid.filter(p=>Number.isFinite(p.ucl)||Number.isFinite(p.lcl)||Number.isFinite(p.u95)||Number.isFinite(p.u998)||Number.isFinite(res.spec?.lo)||Number.isFinite(res.spec?.hi));
 const reasons=[...new Set(flagged.flatMap(p=>p.flags))].join('; '),outside=valid.filter(p=>{const raw=p.raw??p.y;return Number.isFinite(p.ucl)&&p.y>p.ucl||Number.isFinite(p.lcl)&&p.y<p.lcl||Number.isFinite(p.u998)&&p.y>p.u998||Number.isFinite(res.spec?.lo)&&raw<res.spec.lo||Number.isFinite(res.spec?.hi)&&raw>res.spec.hi;}).length;
 return {en:title+'. '+valid.length+' assessed points; '+outside+' beyond available limits; '+flagged.length+' points with recorded flags. '+missing+' missing or non-finite points; '+pre+' before baseline. '+(limits.length?limits.length+' points have available limits. ':'No limits are available; nominal status cannot be established. ')+(res.baselineReady===false?'Control baseline is not ready. ':'')+(reasons?'Recorded flags: '+reasons+'.':'No recorded flags. This is not proof that all data are nominal.'),zh:title+'。评估点 '+valid.length+' 个；超出可用限值 '+outside+' 个；有记录标记 '+flagged.length+' 个。缺失或非有限值 '+missing+' 个；基线之前 '+pre+' 个。'+(limits.length?'有可用限值的点 '+limits.length+' 个。':'没有可用限值，无法确定全部正常。')+(res.baselineReady===false?'控制基线尚未就绪。':'')+(reasons?'记录标记：'+reasons+'。':'没有记录标记，但不代表所有数据均正常。')};
